 void CaptureIntegratedVfxR19(R19VfxReport report,string stage){var sim=WorldR18();string before=(string)Call(sim,"LaunchBodyReceipt");using(var isolation=new RenderIsolation(current.gameObject.scene,(UnityEngine.SceneManagement.Scene)Property(sim,"Scene"))){var c=(Camera)Property(current,"ReviewCamera");var oldP=c.transform.position;var oldQ=c.transform.rotation;float oldSize=c.orthographicSize,oldAspect=c.aspect;var output=Path.Combine(Evidence,"integrated-vfx");Directory.CreateDirectory(output);foreach(var wh in new[]{new[]{390,844},new[]{844,390}}){var rt=new RenderTexture(wh[0],wh[1],24);rt.Create();var prev=RenderTexture.active;c.targetTexture=rt;RenderTexture.active=rt;c.aspect=(float)wh[0]/wh[1];Call(current,"RefreshReviewCamera");Call(current,"TickOverdrivePresentation",.00001f);c.Render();var img=new Texture2D(wh[0],wh[1],TextureFormat.RGB24,false);img.ReadPixels(new Rect(0,0,wh[0],wh[1]),0,0);img.Apply();File.WriteAllBytes(Path.Combine(output,stage+"-"+wh[0]+".png"),img.EncodeToPNG());var fx=Field(current,"overdrivePresentation");report.frames.Add(new R19VfxFrame{stage=stage,width=wh[0],height=wh[1],active=Convert.ToInt32(Property(fx,"ActiveCount")),vertices=Convert.ToInt32(Property(fx,"VertexCount")),cues=Convert.ToInt32(Property(fx,"ContactCues")),breakCues=Convert.ToInt32(Property(fx,"BreakCues")),boostCues=Convert.ToInt32(Property(fx,"BoostCues")),cameraSize=c.orthographicSize,reduced=(bool)Property(current,"ReducedMotion")});c.targetTexture=null;RenderTexture.active=prev;UnityEngine.Object.DestroyImmediate(img);rt.Release();UnityEngine.Object.DestroyImmediate(rt);}c.aspect=oldAspect;c.transform.SetPositionAndRotation(oldP,oldQ);c.orthographicSize=oldSize;Call(current,"TickOverdrivePresentation",.00001f);}report.capturePhysicsInvariant&=before==(string)Call(sim,"LaunchBodyReceipt");}
 [UnityTest]public IEnumerator R19IntegratedVfxCycle(){Directory.CreateDirectory(Evidence);var file=Path.Combine(Evidence,"integrated-vfx-cycle.json");Assert.That(File.Exists(file),Is.False);var r=new R19VfxReport();Action save=()=>File.WriteAllText(file,JsonUtility.ToJson(r,true));yield return NewRetrySubject(false,true,true,true,true,true,true);var aim=JsonUtility.ToJson(new Aim{angle=15,power=57.30769f,direction=1});Call(current,"Configure",JsonUtility.ToJson(new InputSpec{angle=15,power=57.30769f,direction=1}));Call(current,"BeginAim","");Call(current,"PreviewLaunch",aim);Call(current,"BeginSpinCharge","");for(int i=0;i<601;i++){Call(current,"AddSpinWork",JsonUtility.ToJson(new Work{direction=1}));Call(current,"Tick",1f/60);}CaptureIntegratedVfxR19(r,"charge");Call(current,"ReleaseLaunch",aim);var sim=WorldR18();r.launch=JsonUtility.ToJson(Field(State(current),"launchReceipt"));bool peek=false,caseHit=false,group=false;for(int i=0;i<9000&&!(bool)Property(current,"Finished");i++){Call(current,"Tick",1f/60);var state=State(current);var fx=Field(current,"overdrivePresentation");r.peakOverdrive=Math.Max(r.peakOverdrive,Convert.ToInt32(Property(fx,"ActiveCount")));r.peakVertices=Math.Max(r.peakVertices,Convert.ToInt32(Property(fx,"VertexCount")));if(!peek&&F(state,"worldX")>74){CaptureIntegratedVfxR19(r,"mall-approach");peek=true;}int newBreaks=0;bool primaryCase=false;foreach(var e in (IEnumerable)Field(sim,"BreakEvents")){string id=(string)Field(e,"id");if(r18Ids.Contains(id))newBreaks++;if(id==r18Ids[0])primaryCase=true;}if(!caseHit&&primaryCase){CaptureIntegratedVfxR19(r,"case-impact");caseHit=true;}if(!group&&newBreaks==3){CaptureIntegratedVfxR19(r,"group-impact");string body=(string)Call(sim,"LaunchBodyReceipt");Call(current,"SetReducedMotion","1");CaptureIntegratedVfxR19(r,"group-reduced");r.reducedPhysicsInvariant=body==(string)Call(sim,"LaunchBodyReceipt");Call(current,"SetReducedMotion","0");float time=F(State(current),"time"),stop=F(State(current),"hitStopRemaining");Call(current,"SetPaused","1");Call(current,"Tick",.2f);r.pauseStable=F(State(current),"time")==time&&F(State(current),"hitStopRemaining")==stop;Call(current,"SetPaused","0");group=true;save();}}r.final=JsonUtility.ToJson(State(current));r.breakTrace=(string)Call(sim,"ReviewContactTraceJson");foreach(var e in (IEnumerable)Field(sim,"BreakEvents"))r.breaks.Add(new BreakRecord{id=(string)Field(e,"id"),material=(string)Field(e,"material"),secondary=(bool)Field(e,"secondary"),time=F(e,"time"),position=(Vector3)Field(e,"position")});CaptureIntegratedVfxR19(r,"result");Call(current,"RetryLaunch","");var retry=Field(current,"overdrivePresentation");r.retryCountersReset=Convert.ToInt32(Property(retry,"ContactCues"))==0&&Convert.ToInt32(Property(retry,"BreakCues"))==0&&Convert.ToInt32(Property(retry,"BoostCues"))==0;save();Assert.That(peek&&caseHit&&group&&r.capturePhysicsInvariant&&r.pauseStable&&r.reducedPhysicsInvariant&&r.retryCountersReset,Is.True);Assert.That(r.peakOverdrive,Is.LessThanOrEqualTo(40));Assert.That(r.peakVertices,Is.LessThanOrEqualTo(4096));Call(current,"ShutdownReviewPhysics");current=null;yield return null;}
